html,body{height:100%;background:transparent}
/* 拖拽/点按时不要出系统的高亮方块和文字选取 —— 那两样在安卓壳里看起来就是「一直闪」 */
*{-webkit-tap-highlight-color:transparent}
#ball,#grab,#fold,.face{user-select:none;-webkit-user-select:none;touch-action:none}
#orb{width:100%;height:100%;position:relative}

/* ── 收起：一颗球 ──
   宿主用 slot.shape 的 clip-path 把窗口裁成圆形，所以球外面那圈透明区域
   点得穿，底下的界面照样能用。球自己只管好看。 */
#ball{position:absolute;inset:0;border-radius:50%;cursor:grab;
      background:radial-gradient(circle at 32% 28%, #8fb4ff 0%, #5a7dff 45%, #3a4fd8 100%);
      box-shadow:0 6px 18px rgba(58,79,216,.45), inset 0 -6px 12px rgba(0,0,0,.22),
