entry.js:
// 「悬浮挂件」示例：宿主一根线都不画（slot.chrome:'none'），整个物体由本文件自己画。
// 窗口本身的行为走 nuo.window.*：
//   dragHandle(el)  把元素变成拖拽把手（球体本身 / 面板标题栏都行）
//   resize(w,h)     切换形态时把窗口尺寸一起换掉 —— 球 64×64，面板 230×210
//   close()         想要关闭按钮就自己画一个来调它；不想要就不画（本例就没画）
// 配合 manifest 的 shape:'circle'：宿主用 clip-path 裁容器，球外的透明区域点得穿。
var $ = function (id) { return document.getElementById(id); };
var BALL = { w: 64, h: 64 };
// 点/拖的判据：手指按下时必然有几像素抖动，阈值给太小（曾经是 5px）
// 就会把「点一下」误判成拖拽，症状是要戳好几次才展开
var TAP_MOVE = 12;   // px
var TAP_MS = 600;
var PANEL = { w: 230, h: 210 };
var opened = false;
var saveTimer = null;

function setOpen(v) {
  opened = !!v;
  document.body.className = opened ? 'open' : '';
  var s = opened ? PANEL : BALL;
  nuo.window.resize(s.w, s.h);
  // 形状随形态换：面板是圆角矩形，球是正圆
  nuo.window.shape(opened ? 'inset(0 round 16px)' : 'circle(50%)');
}

// 点球展开。⚠️ 要和拖拽区分：拖过就不算点击，否则拖到一半松手会莫名展开
var down = null;
$('ball').addEventListener('pointerdown', function (e) { down = { x: e.clientX, y: e.clientY, t: Date.now() }; });
$('ball').addEventListener('pointerup', function (e) {
  if (!down) return;
  var moved = Math.max(Math.abs(e.clientX - down.x), Math.abs(e.clientY - down.y));
  var held = Date.now() - down.t;
  down = null;
  if (moved <= TAP_MOVE && held <= TAP_MS) setOpen(true);
});
$('ball').addEventListener('pointercancel', function () { down = null; });
$('fold').addEventListener('click', function () { setOpen(false); });

// 球体和面板标题栏都能拖 —— 宿主只收位移量，不需要知道 iframe 在哪
nuo.window.dragHandle($('ball'));
nuo.window.dragHandle($('grab'));

// 时钟：球面上顺手显示，让它看起来像个活的东西而不是一张贴纸
function tick() {
  var d = new Date();
  var h = d.getHours();
  $('clock').textContent = (h < 10 ? '0' + h : h) + ':' + ('0' + d.getMinutes()).slice(-2);
  $('emoji').textContent = h < 6 ? '🌙' : h < 11 ? '☀️' : h < 18 ? '🌤' : h < 22 ? '🌆' : '🌙';
}
tick();
setInterval(tick, 20000);

// 便签内容存在插件自己的 KV 里（storage 是隐含能力，不用申请权限）
$('note').addEventListener('input', function () {
  $('saved').textContent = '保存中…';
  clearTimeout(saveTimer);
  saveTimer = setTimeout(function () {
    nuo.storage.set('note', $('note').value).then(function () {
      $('saved').textContent = '已保存';
    }).catch(function () { $('saved').textContent = '保存失败'; });
  }, 400);
});
$('clear').addEventListener('click', function () {
  $('note').value = '';
  nuo.storage.set('note', '').catch(function () {});
  $('saved').textContent = '已清空';
});

nuo.storage.get('note').then(function (v) {
  if (typeof v === 'string') $('note').value = v;
}).catch(function () {}).then(function () {
  nuo.ready();
  setOpen(false);
});

// 悬浮播放器示例
//
// 数据通路：宿主建的 blob: URL 在 null origin 的 iframe 里取不到，
// 所以音频以 ArrayBuffer 过桥，由插件在【自己的 origin】里 createObjectURL
// 之后再喂给 <audio>。CSP 的 media-src 允许 blob: 正是为了这条路。
//
// 添加曲目走 nuo.media.pick()：由【宿主】开选择器、抓字节、存起来，只把 id 回给插件。
// 插件全程碰不到 URL —— 这是支持网址的唯一安全做法（放宽 CSP 会开出外连通道）。

var el = {};
['title','prog','bar','play','prev','next','time','msg','add','del'].forEach(function(k){ el[k] = document.getElementById(k); });

var audio = new Audio();
var tracks = [];        // [{id, name}]
var idx = 0;
var urlCache = {};
var cfg = { volume: 80, loop: false };

function fmt(s){ if(!isFinite(s)||s<0) s=0; var m=Math.floor(s/60), r=Math.floor(s%60); return m+':'+(r<10?'0':'')+r; }
function say(t){ el.msg.textContent = t || ''; }
function setPlayIcon(){ el.play.textContent = audio.paused ? '▶' : '⏸'; }

function sync(){
  var n = tracks.length;
  el.play.disabled = n === 0;
  el.prev.disabled = n < 2;
  el.next.disabled = n < 2;
  el.del.disabled = n === 0;
  if (!n) { el.title.textContent = '—'; say('点 ＋ 添加曲目'); }
  else { el.title.textContent = tracks[idx] ? (tracks[idx].name || ('#' + tracks[idx].id)) : '—'; }
}

function persist(){ return nuo.storage.set('tracks', JSON.stringify(tracks)); }

async function urlFor(t){
  if (urlCache[t.id]) return urlCache[t.id];
  var buf;
  try { buf = await nuo.media.read(t.id); }
  catch (e) { nuo.log('media.read 失败 ' + t.id + ': ' + (e && e.message)); return null; }
  if (!buf || !buf.byteLength) return null;
  var url = nuo.media.toObjectUrl(buf, 'audio/mpeg');
  urlCache[t.id] = url;
  return url;
}

async function load(i, autoplay){
  if (!tracks.length) { sync(); return; }
  idx = (i + tracks.length) % tracks.length;
  var t = tracks[idx];
  el.title.textContent = t.name || ('#' + t.id);
  say('载入中…');
  var url = await urlFor(t);
  if (!url) { say('这个文件读不到了'); return; }
  audio.src = url;
  audio.volume = Math.max(0, Math.min(1, cfg.volume / 100));
  say('');
  if (autoplay) {
    // 自动播放策略：只有用户手势触发的那一次才会成功。被拒时不报错，提示用户点一下。
    audio.play().then(setPlayIcon).catch(function(){ say('点播放键开始（浏览器要求手势）'); setPlayIcon(); });
  }
  setPlayIcon();
}

el.play.addEventListener('click', function(){
  if (!tracks.length) return;
  if (!audio.src) { load(idx, true); return; }
  if (audio.paused) audio.play().then(setPlayIcon).catch(function(e){ say('播放被拒: ' + (e && e.name)); });
  else { audio.pause(); setPlayIcon(); }
});

el.next.addEventListener('click', function(){ load(idx + 1, true); });
el.prev.addEventListener('click', function(){ load(idx - 1, true); });

el.add.addEventListener('click', async function(){
  say('选择文件或粘贴网址…');
  var picked;
  try { picked = await nuo.media.pick('audio'); }
  catch (e) { say('添加失败'); nuo.log(String(e && e.message)); return; }
  if (!picked || !picked.id) { say(tracks.length ? '' : '点 ＋ 添加曲目'); return; }
  tracks.push({ id: picked.id, name: picked.name || ('#' + picked.id) });
  await persist();
  say(tracks.length + ' 首');
  // sync() 必须先跑：load() 不管按钮状态，只走 load 的话播放键会一直是灰的
  sync();
  // 第一首自动开播；后续只加进列表不打断当前播放
  if (tracks.length === 1) load(0, true);
});

el.del.addEventListener('click', async function(){
  if (!tracks.length) return;
  var gone = tracks.splice(idx, 1)[0];
  if (gone) delete urlCache[gone.id];
  await persist();
  audio.pause(); audio.src = '';
  if (tracks.length) { load(idx, false); } else { sync(); setPlayIcon(); }
});

el.bar.addEventListener('click', function(ev){
  if (!audio.duration || !isFinite(audio.duration)) return;
  var r = el.bar.getBoundingClientRect();
  audio.currentTime = ((ev.clientX - r.left) / r.width) * audio.duration;
});

audio.addEventListener('timeupdate', function(){
  if (audio.duration && isFinite(audio.duration)) el.prog.style.width = ((audio.currentTime / audio.duration) * 100) + '%';
  el.time.textContent = fmt(audio.currentTime);
});

audio.addEventListener('ended', function(){
  if (cfg.loop) { audio.currentTime = 0; audio.play().catch(function(){}); }
  else if (tracks.length > 1) load(idx + 1, true);
  else setPlayIcon();
});

audio.addEventListener('error', function(){ say('这个文件解不了码'); });

async function init(){
  var s = await nuo.storage.getAll();
  if (s && typeof s === 'object') {
    if (s.volume) cfg.volume = parseInt(s.volume, 10) || 80;
    cfg.loop = !!s.loop;
    if (s.tracks) {
      try { var arr = JSON.parse(s.tracks); if (Array.isArray(arr)) tracks = arr.filter(function(t){ return t && t.id != null; }); }
      catch (e) { nuo.log('曲目列表损坏，已重置'); }
    }
  }
  audio.volume = Math.max(0, Math.min(1, cfg.volume / 100));
  sync();
  setPlayIcon();
  if (tracks.length) say(tracks.length + ' 首');
}

init().then(function(){ nuo.ready(); }).catch(function(e){ say('初始化失败'); nuo.log(String(e && e.message)); nuo.ready(); });

