entry.js:
// 预设开关：只改「哪些条目开着」和「全局用哪套预设」，条目内容一个字都不碰。
// 语义与预设编辑页完全一致（读写的就是同一份预设），分组开关 = 一次开 / 关组内全部条目。
var $ = function (id) { return document.getElementById(id); };
var state = null;      // 宿主回来的快照
var scope = 'online';  // online | offline
var charName = '';
var open = {};         // groupId -> 是否展开
var busy = false;

// 面板挂在「此时此刻」里 → 默认就看线下那一套，省一次点击
if (document.body.getAttribute('data-slot') === 'appPanel') scope = 'offline';

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
  });
}

function errText(e) {
  var m = (e && e.message) || String(e || '');
  if (m.indexOf('presetBuiltin') >= 0) return '内置预设不能改开关，先去「预设」页复制一份';
  if (m.indexOf('presetNotFound') >= 0) return '这套预设已经不在了，点右上角刷新';
  return m;
}

function paintScope() {
  var bs = document.querySelectorAll('#scope .sg');
  for (var i = 0; i < bs.length; i++) {
    bs[i].className = 'sg' + (bs[i].getAttribute('data-scope') === scope ? ' on' : '');
  }
}

function paintWho() {
  var txt = charName ? ('当前：' + charName) : '';
  $('who').textContent = txt;
  $('who').className = txt ? '' : 'hide';
}

function show(text) {
  $('msg').textContent = text;
  $('msg').className = text ? '' : 'hide';
  $('list').innerHTML = '';
  $('foot').textContent = '';
  $('search').className = 'hide';
}

function load() {
  paintScope();
  return nuo.context().then(function (c) {
    var charId = c && c.charId ? String(c.charId) : null;
    charName = (c && c.charName) || '';
    paintWho();
    return nuo.preset.config({ charId: charId, scope: scope }).then(function (s) {
      state = s;
      render();
    });
  }).catch(function (e) { show('读取失败：' + errText(e)); });
}

function nameOf(id) {
  var p = (state.presets || []).filter(function (x) { return x.id === id; })[0];
  return p ? (p.name || '未命名预设') : '';
}

// 预设选择：跟随全局 → 可切（改的是全局）；绑了专属 → 只读，请去聊天设定换
function renderPick() {
  var sel = $('sel');
  var bound = state.boundId && state.boundId !== '__default__';
  var html = '';
  var cur = state.preset ? state.preset.id : '';
  if (state.boundId === '__default__') html += '<option value="">原始模板（无条目）</option>';
  (state.presets || []).forEach(function (p) {
    html += '<option value="' + esc(p.id) + '"' + (p.id === cur ? ' selected' : '') + '>'
      + esc(p.name || '未命名预设') + (p.builtin ? '（内置）' : '') + '</option>';
  });
  sel.innerHTML = html;
  if (state.boundId === '__default__') sel.value = '';
  sel.disabled = !!state.boundId || busy;
  $('pickHint').innerHTML = state.boundId
    ? ('这个聊天在聊天设定里绑定了专属预设' + (bound ? '「<b>' + esc(nameOf(state.boundId) || state.preset && state.preset.name) + '</b>」' : '（原始模板）')
      + '，要换请去聊天设定；下面改的就是它')
    : '切换的是<b>全局</b>预设：跟随全局的聊天会一起换';
  $('pick').className = '';
}

function render() {
  if (!state) return;
  $('msg').className = 'hide';
  renderPick();

  var p = state.preset;
  if (!p) { show('这里用的是原始模板，没有可开关的条目'); return; }
  var items = p.items || [];
  var ro = !!p.builtin;
  var toggles = items.filter(function (it) { return it.kind !== 'group'; });
  if (!toggles.length) { show('这套预设没有可开关的条目'); return; }

  $('search').className = '';
  var q = $('q').value.trim().toLowerCase();
  var hit = function (it) { return !q || (it.name || '').toLowerCase().indexOf(q) >= 0 || (it.note || '').toLowerCase().indexOf(q) >= 0; };

  // 按分组归拢（顺序保持预设里的顺序）
  var groups = {};
  items.forEach(function (it) { if (it.kind === 'group') groups[it.id] = { head: it, mem: [] }; });
  toggles.forEach(function (it) { if (it.group && groups[it.group]) groups[it.group].mem.push(it); });

  var html = '', onCnt = 0, shown = 0;
  toggles.forEach(function (it) { if (it.enabled) onCnt++; });

  function itemRow(it, small) {
    return '<div class="row"><span class="nm"><b><em>' + esc(it.name || '未命名条目') + '</em>'
      + (it.kind === 'system' ? '<span class="tag">系统</span>' : '') + '</b>'
      + (it.note ? '<i>' + esc(it.note) + '</i>' : '') + '</span>'
      + '<label class="sw' + (small ? ' sm' : '') + '"><input type="checkbox" data-it="' + esc(it.id) + '"'
      + (it.enabled ? ' checked' : '') + (ro ? ' disabled' : '') + '><i></i></label></div>';
  }

  items.forEach(function (it) {
    if (it.kind === 'group') {
      var g = groups[it.id];
      var hitHead = hit(it);
      var mem = hitHead ? g.mem : g.mem.filter(hit);
      if (!mem.length && !(hitHead && !q)) return;
      shown++;
      var on = g.mem.some(function (m) { return m.enabled; });
      var live = g.mem.filter(function (m) { return m.enabled; }).length;
      var expanded = !!open[it.id] || (!!q && !hitHead);
      html += '<div class="card"><div class="row gr">'
        + '<button class="arw' + (expanded ? ' op' : '') + '" data-arw="' + esc(it.id) + '">&#9654;</button>'
        + '<span class="nm"><b><em>' + esc(it.name || '未命名分组') + '</em><span class="tag">分组</span></b>'
        + '<i>' + (g.mem.length ? (live + ' / ' + g.mem.length + ' 条开着') : '空分组') + '</i></span>'
        + '<label class="sw"><input type="checkbox" data-grp="' + esc(it.id) + '"'
        + (on ? ' checked' : '') + ((ro || !g.mem.length) ? ' disabled' : '') + '><i></i></label></div>';
      if (expanded && mem.length) {
        html += '<div class="mem">';
        if (!ro) {
          html += '<div class="all"><button data-all="on" data-gid="' + esc(it.id) + '">全开</button>'
            + '<button data-all="off" data-gid="' + esc(it.id) + '">全关</button></div>';
        }
        mem.forEach(function (m) { html += itemRow(m, true); });
        html += '</div>';
      }
      html += '</div>';
      return;
    }
    if (it.group && groups[it.group]) return;   // 组内条目随分组画
    if (!hit(it)) return;
    shown++;
    html += '<div class="card">' + itemRow(it, false) + '</div>';
  });

  $('list').className = ro ? 'ro' : '';
  $('list').innerHTML = shown ? html
    : '<div style="font-size:11.5px;opacity:.6;text-align:center;padding:24px 12px">没有匹配的条目</div>';
  $('foot').textContent = ro
    ? '内置预设只能看，想开关先去「预设」页复制一份'
    : ('「' + (p.name || '未命名预设') + '」开着 ' + onCnt + ' / ' + toggles.length + ' 条');
}

// 写回：{ 条目id: 开/关 }，只送有变化的
function persist(changes) {
  if (!state || !state.preset || state.preset.builtin || busy) return Promise.resolve();
  busy = true;
  return nuo.preset.set(scope, state.preset.id, changes).then(function () {
    busy = false;
    state.preset.items.forEach(function (it) {
      if (Object.prototype.hasOwnProperty.call(changes, it.id)) it.enabled = !!changes[it.id];
    });
    render();
  }).catch(function (e) { busy = false; show('保存失败：' + errText(e)); });
}

function groupChanges(gid, on) {
  var ch = {};
  state.preset.items.forEach(function (it) {
    if (it.kind !== 'group' && it.group === gid && !!it.enabled !== on) ch[it.id] = on;
  });
  return ch;
}

// 事件委托：列表整块重绘，逐个绑定会随重绘一起失效
$('list').addEventListener('click', function (ev) {
  var t = ev.target;
  var arw = t.getAttribute && t.getAttribute('data-arw');
  if (arw) {
    open[arw] = !open[arw];
    try { nuo.storage.set('open', open); } catch (e) {}
    render();
    return;
  }
  var all = t.getAttribute && t.getAttribute('data-all');
  if (all && state && state.preset) persist(groupChanges(t.getAttribute('data-gid'), all === 'on'));
});

$('list').addEventListener('change', function (ev) {
  var t = ev.target;
  if (!state || !state.preset) return;
  var gid = t.getAttribute('data-grp');
  if (gid) { persist(groupChanges(gid, t.checked)); return; }
  var id = t.getAttribute('data-it');
  if (id) { var ch = {}; ch[id] = t.checked; persist(ch); }
});

$('sel').addEventListener('change', function () {
  var id = this.value;
  if (!state || state.boundId || !id || busy) return;
  busy = true;
  nuo.preset.activate(scope, id).then(function () {
    busy = false;
    load();
  }).catch(function (e) { busy = false; show('切换失败：' + errText(e)); });
});

$('q').addEventListener('input', function () { render(); });
$('refresh').addEventListener('click', function () { load(); });

var sgs = document.querySelectorAll('#scope .sg');
for (var k = 0; k < sgs.length; k++) {
  sgs[k].addEventListener('click', function () {
    scope = this.getAttribute('data-scope');
    try { nuo.storage.set('scope', scope); } catch (e) {}
    load();
  });
}

// 换聊天了就重读 —— 悬浮窗是常驻的，不重读会对着上一个角色的预设开关
nuo.on('chatOpen', function () { load(); });

Promise.all([
  nuo.storage.get('scope').catch(function () { return null; }),
  nuo.storage.get('open').catch(function () { return null; })
]).then(function (r) {
  if (document.body.getAttribute('data-slot') !== 'appPanel' && (r[0] === 'online' || r[0] === 'offline')) scope = r[0];
  if (r[1] && typeof r[1] === 'object') open = r[1];
}).then(function () {
  nuo.ready();
  load();
});

// 装饰器插件必须写成「收到数据就重绘」——宿主会回收复用 iframe，
// 靠 on('render') 换数据而不是重建文档（见 pluginSrcDoc.js 说明）。
var cfg = { var1: '好感度', var2: '心情', barMax: 100, showOnUser: false, everyMsg: false };
// 最後一次收到的訊息 —— 變量改了要重繪時沒有它就不知道該畫什麼
var lastMsg = null;
var el = {
  card: document.getElementById('card'), hint: document.getElementById('hint'),
  r1: document.getElementById('r1'), r2: document.getElementById('r2'),
  l1: document.getElementById('l1'), v1: document.getElementById('v1'), b1: document.getElementById('b1'),
  l2: document.getElementById('l2'), v2: document.getElementById('v2')
};

function fit() { nuo.ui.resize(document.body.scrollHeight); }

function hideAll() {
  el.card.className = 'hidden';
  el.hint.className = 'hidden';
  nuo.ui.resize(0);
}

// 一个变量都没有时，只在【最新一条】下面留一行提示。
// 完全隐藏的话，用户分不清「插件在跑但没数据」和「插件根本没装上」——
// 示例插件尤其不能让人有这种疑惑。挂在每条消息下面又太吵，所以只挂最后一条。
function showHint() {
  el.card.className = 'hidden';
  el.hint.className = '';
  el.hint.textContent = '状态卡已启用：去「聊天设定 → 聊天变量」加一个「' + cfg.var1 + '」就会显示在这里';
  fit();
}

async function loadCfg() {
  var s = await nuo.storage.getAll();
  if (s && typeof s === 'object') {
    if (s.var1) cfg.var1 = s.var1;
    if (s.var2) cfg.var2 = s.var2;
    if (s.barMax) cfg.barMax = parseInt(s.barMax, 10) || 100;
    cfg.showOnUser = !!s.showOnUser;
    cfg.everyMsg = !!s.everyMsg;
  }
}

async function render(msg) {
  if (!msg) { hideAll(); return; }
  // 變量只有「當前值」一個，掛在每條歷史訊息下面就是同一個數字重複幾十遍 ——
  // 又吵又占地方（而且每條都是一個 iframe）。預設只挂最新一條。
  if (!cfg.everyMsg && !msg.isLast) { hideAll(); return; }
  if (msg.role === 'user' && !cfg.showOnUser) { hideAll(); return; }

  var bag;
  // snapTs = 下一条消息的时间（宿主在 render 事件里给）。
  // 带上它拿到的就是「这条消息当时」的值——没它的话往回捲每张卡显示的都是现在的值。
  // 轨迹里没那么早的记录时宿主会自动退回现值。
  try { bag = await nuo.vars.getAll({ at: msg.snapTs }); } catch (e) { hideAll(); return; }
  var local = (bag && bag.local) || {};

  var raw1 = local[cfg.var1];
  var raw2 = local[cfg.var2];

  if (raw1 === undefined && raw2 === undefined) {
    if (msg.isLast) showHint(); else hideAll();
    return;
  }

  el.hint.className = 'hidden';
  el.card.className = '';

  if (raw1 === undefined) {
    el.r1.style.display = 'none';
  } else {
    el.r1.style.display = '';
    var n = parseFloat(raw1);
    if (isNaN(n)) {
      // 非数值就当文字显示，不硬套进度条
      el.l1.textContent = cfg.var1; el.v1.textContent = String(raw1); el.b1.style.width = '0';
    } else {
      var pct = Math.max(0, Math.min(100, (n / cfg.barMax) * 100));
      el.l1.textContent = cfg.var1;
      el.v1.textContent = n + ' / ' + cfg.barMax;
      el.b1.style.width = pct + '%';
    }
  }

  if (raw2 === undefined) {
    el.r2.style.display = 'none';
  } else {
    el.r2.style.display = '';
    el.l2.textContent = cfg.var2;
    el.v2.textContent = String(raw2);
  }

  fit();
}

nuo.on('render', function (msg) { lastMsg = msg; render(msg); });

// 變量被改了（AI 的 <var> 標記 / 用戶在「聊天設定 → 聊天變量」手改 / 觸發器）。
// 沒有這一條的話，卡片只在【訊息變動】時才重讀 —— 用戶改完數值盯著進度條
// 一動不動，只能退出重進，看起來就像壞了。
nuo.on('vars', function () { if (lastMsg) render(lastMsg); });

loadCfg().then(function () { nuo.ready(); }).catch(function () { nuo.ready(); });

